using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
[InitializeOnLoad]public static class DirectCrankSetupTemp{
 static DirectCrankSetupTemp(){EditorApplication.delayCall+=()=>{if(Application.isPlaying||File.Exists("Temp/DirectCrankSetupDone"))return;var jack=Object.FindObjectOfType<JackInTheBoxInteraction>();if(jack==null)return;var so=new SerializedObject(jack);var crank=(Transform)so.FindProperty("crank").objectReferenceValue;var axis=so.FindProperty("crankAxis").vector3Value.normalized;var skin=jack.GetComponentInChildren<SkinnedMeshRenderer>();int index=System.Array.IndexOf(skin.bones,crank);var mesh=skin.sharedMesh;var vertices=mesh.vertices;var weights=mesh.boneWeights;float maxRadius=0;for(int i=0;i<vertices.Length;i++){var w=weights[i];if(w.boneIndex0!=index||w.weight0<.7f)continue;var p=mesh.bindposes[index].MultiplyPoint3x4(vertices[i]);maxRadius=Mathf.Max(maxRadius,Vector3.ProjectOnPlane(p,axis).magnitude);}Vector3 gripPosition=Vector3.zero;int count=0;for(int i=0;i<vertices.Length;i++){var w=weights[i];if(w.boneIndex0!=index||w.weight0<.7f)continue;var p=mesh.bindposes[index].MultiplyPoint3x4(vertices[i]);if(Vector3.ProjectOnPlane(p,axis).magnitude>=maxRadius*.88f){gripPosition+=p;count++;}}if(count==0)throw new System.Exception("Crank knob vertices not found");gripPosition/=count;var grip=crank.Find("Crank Grip");if(grip==null){grip=new GameObject("Crank Grip").transform;grip.SetParent(crank,false);}grip.localPosition=gripPosition;so.FindProperty("crankGrip").objectReferenceValue=grip;so.ApplyModifiedPropertiesWithoutUndo();var ui=(GameObject)so.FindProperty("windingUI").objectReferenceValue;var oldWheel=ui.transform.Find("Winding Controls/Wheel Background");if(oldWheel!=null)Undo.DestroyObjectImmediate(oldWheel.gameObject);var label=ui.GetComponentsInChildren<Text>(true).First(t=>t.name=="Wheel Instructions");label.text="Hold LMB on the crank and turn";var rect=label.rectTransform;rect.anchorMin=new Vector2(.6f,.32f);rect.anchorMax=new Vector2(.97f,.4f);rect.offsetMin=rect.offsetMax=Vector2.zero;EditorSceneManager.MarkSceneDirty(jack.gameObject.scene);EditorSceneManager.SaveScene(jack.gameObject.scene);File.WriteAllText("Temp/DirectCrankSetupDone","Grip vertices="+count+" local="+gripPosition.ToString("F6")+" old UI wheel removed.");};}
}
